/* «Жизнь» и клеточные автоматы на черновом листе «Жизнь».
   Поле — квадратные клетки чернового листа; поколения рисуются слоем декораций: книга не меняется,
   журнал отмены и «изменено» не трогаются. Рисуют выделением: кисть «Рисовать» оживляет выделенные клетки. */
/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
/* ===== Клеточные автоматы: поле, правила B/S, «Мозг Брайана», одномерные правила, RLE ===== */
const ЖИЗНЬ = (() => {
  /* правило «B3/S23» → {рожд: Set, жив: Set} */
  function правило(текст){
    const т = String(текст || '').toUpperCase().replace(/\s/g, '');
    let m = т.match(/^B([0-8]*)\/?S([0-8]*)$/) || т.match(/^([0-8]*)\/([0-8]*)$/);
    if(!m) throw new Error('Правило пишется как B3/S23: после B — сколько соседей рождают клетку, после S — при скольких она живёт');
    if(/^[0-8]*\/[0-8]*$/.test(т)) m = [т, m[2], m[1]];          /* старая запись «23/3» — сначала выживание */
    return {рожд: new Set([...m[1]].map(Number)), жив: new Set([...m[2]].map(Number)), b: m[1], s: m[2]};
  }
  function поле(w, h){ return {w, h, к: new Uint8Array(w * h), в: new Uint16Array(w * h)}; }
  /* следующее поколение: вид 'bs' (правило B/S), 'мозг' (три состояния), 'одномерный' (правило 0…255, строка за строкой) */
  function шаг(п, как){
    const {w, h, к, в} = п, тор = !!как.тор;
    const н = new Uint8Array(w * h), нв = new Uint16Array(w * h);
    if(как.вид === 'одномерный'){
      /* последняя заполненная строка → следующая; поле кончилось — сдвиг вверх */
      let r = как.строка == null ? 0 : как.строка;
      const src = r, dst = r + 1;
      let base = к;
      if(dst >= h){ н.set(к.subarray(w)); нв.set(в.subarray(w)); base = н; }
      else { н.set(к); нв.set(в); }
      const из = dst >= h ? h - 2 : src, в2 = dst >= h ? h - 1 : dst;
      for(let c = 0; c < w; c++){
        const л = c > 0 ? base[из * w + c - 1] : (тор ? base[из * w + w - 1] : 0);
        const ц = base[из * w + c];
        const п2 = c < w - 1 ? base[из * w + c + 1] : (тор ? base[из * w] : 0);
        const код = (л ? 4 : 0) | (ц ? 2 : 0) | (п2 ? 1 : 0);
        н[в2 * w + c] = (как.номер >> код) & 1;
        нв[в2 * w + c] = н[в2 * w + c] ? 1 : 0;
      }
      return {п: {w, h, к: н, в: нв}, строка: Math.min(dst, h - 1)};
    }
    const мозг = как.вид === 'мозг', пр = как.правило;
    for(let r = 0; r < h; r++){
      for(let c = 0; c < w; c++){
        let s = 0;
        for(let dr = -1; dr <= 1; dr++){
          let rr = r + dr;
          if(rr < 0 || rr >= h){ if(!тор) continue; rr = (rr + h) % h; }
          for(let dc = -1; dc <= 1; dc++){
            if(!dr && !dc) continue;
            let cc = c + dc;
            if(cc < 0 || cc >= w){ if(!тор) continue; cc = (cc + w) % w; }
            if(к[rr * w + cc] === 1) s++;
          }
        }
        const i = r * w + c, был = к[i];
        if(мозг){
          if(был === 1) н[i] = 2; else if(был === 2) н[i] = 0; else if(s === 2) н[i] = 1;
        } else if(был) н[i] = пр.жив.has(s) ? 1 : 0;
        else н[i] = пр.рожд.has(s) ? 1 : 0;
        if(н[i]) нв[i] = был ? Math.min(65535, в[i] + 1) : 1;
      }
    }
    return {п: {w, h, к: н, в: нв}};
  }
  const живых = п => { let n = 0; for(let i = 0; i < п.к.length; i++) if(п.к[i]) n++; return n; };
  /* отпечаток поля для поиска повторов */
  function отпечаток(п){ let h1 = 2166136261 >>> 0, h2 = 5381; for(let i = 0; i < п.к.length; i++){ const v = п.к[i]; h1 = Math.imul(h1 ^ v, 16777619) >>> 0; h2 = (Math.imul(h2, 33) + v) >>> 0; } return h1.toString(36) + '.' + h2.toString(36); }
  /* RLE (формат LifeWiki): «x = 3, y = 3, rule = B3/S23» и «bo$2bo$3o!» */
  function изRLE(текст){
    const строки = String(текст || '').split(/\r?\n/).filter(x => !/^\s*#/.test(x));
    let правилоТ = null, i = 0;
    const шапка = строки.findIndex(x => /^\s*x\s*=/.test(x));
    if(шапка >= 0){ const m = строки[шапка].match(/rule\s*=\s*([^\s,]+)/i); if(m) правилоТ = m[1]; i = шапка + 1; }
    const тело = строки.slice(i).join('').replace(/\s/g, '');
    if(!тело) throw new Error('В тексте RLE нет фигуры');
    const клетки = []; let r = 0, c = 0, n = '';
    for(const ch of тело){
      if(/\d/.test(ch)){ n += ch; continue; }
      const k = n ? parseInt(n, 10) : 1; n = '';
      if(ch === 'b' || ch === '.'){ c += k; }
      else if(ch === 'o' || ch === 'A' || /[A-Z]/.test(ch)){ for(let j = 0; j < k; j++) клетки.push([r, c + j]); c += k; }
      else if(ch === '$'){ r += k; c = 0; }
      else if(ch === '!') break;
      else throw new Error('В RLE непонятный знак «' + ch + '»');
    }
    const h = клетки.length ? Math.max(...клетки.map(x => x[0])) + 1 : 0, w = клетки.length ? Math.max(...клетки.map(x => x[1])) + 1 : 0;
    return {клетки, w, h, правило: правилоТ};
  }
  function вRLE(п, правилоТ){
    let r1 = п.h, r2 = -1, c1 = п.w, c2 = -1;
    for(let r = 0; r < п.h; r++) for(let c = 0; c < п.w; c++) if(п.к[r * п.w + c] === 1){ r1 = Math.min(r1, r); r2 = Math.max(r2, r); c1 = Math.min(c1, c); c2 = Math.max(c2, c); }
    if(r2 < 0) return 'x = 0, y = 0, rule = ' + (правилоТ || 'B3/S23') + '\n!';
    const ряды = [];
    for(let r = r1; r <= r2; r++){
      let s = '', пред = null, k = 0;
      const сбросить = () => { if(k) s += (k > 1 ? k : '') + пред; };
      for(let c = c1; c <= c2; c++){ const ch = п.к[r * п.w + c] === 1 ? 'o' : 'b'; if(ch === пред) k++; else { сбросить(); пред = ch; k = 1; } }
      if(пред === 'o') сбросить();
      ряды.push(s);
    }
    /* пустые строки подряд сворачиваются в «3$» */
    let тело = '', пусто = 0;
    ряды.forEach((s, i) => { if(i === 0){ тело = s; return; } if(!s){ пусто++; return; } тело += (пусто + 1 > 1 ? (пусто + 1) : '') + '$' + s; пусто = 0; });
    const строки = []; let строка = '';
    for(const кус of тело.match(/\d*[bo$]/g) || []){ if((строка + кус).length > 68){ строки.push(строка); строка = ''; } строка += кус; }
    строки.push(строка + '!');
    return 'x = ' + (c2 - c1 + 1) + ', y = ' + (r2 - r1 + 1) + ', rule = ' + (правилоТ || 'B3/S23') + '\n' + строки.join('\n');
  }
  return {правило, поле, шаг, живых, отпечаток, изRLE, вRLE};
})();
/* ===== конец куска «Клеточные автоматы» ===== */
const ФИГУРЫ = [{"имя":"Планер","вид":"корабли","rle":"bo$2bo$3o!"},{"имя":"Лёгкий корабль","вид":"корабли","rle":"bo2bo$o4b$o3bo$4o!"},{"имя":"Средний корабль","вид":"корабли","rle":"3bo2b$bo3bo$o5b$o4bo$5o!"},{"имя":"Тяжёлый корабль","вид":"корабли","rle":"3b2o2b$bo4bo$o6b$o5bo$6o!"},{"имя":"Ружьё Госпера","вид":"ружья","rle":"24bo$22bobo$12b2o6b2o12b2o$11bo3bo4b2o12b2o$2o8bo5bo3b2o$2o8bo3bob2o4bobo$10bo5bo7bo$11bo3bo$12b2o!"},{"имя":"Мигалка","вид":"осцилляторы","rle":"3o!"},{"имя":"Жаба","вид":"осцилляторы","rle":"b3o$3o!"},{"имя":"Маяк","вид":"осцилляторы","rle":"2o2b$2o2b$2b2o$2b2o!"},{"имя":"Пульсар","вид":"осцилляторы","rle":"2b3o3b3o2b2$o4bobo4bo$o4bobo4bo$o4bobo4bo$2b3o3b3o2b2$2b3o3b3o2b$o4bobo4bo$o4bobo4bo$o4bobo4bo2$2b3o3b3o!"},{"имя":"Пентадекатлон","вид":"осцилляторы","rle":"2bo4bo2b$2ob4ob2o$2bo4bo!"},{"имя":"Галактика Кока","вид":"осцилляторы","rle":"6ob2o$6ob2o$7b2o$2o5b2o$2o5b2o$2o5b2o$2o7b$2ob6o$2ob6o!"},{"имя":"Блок","вид":"устойчивые","rle":"2o$2o!"},{"имя":"Улей","вид":"устойчивые","rle":"b2o$o2bo$b2o!"},{"имя":"Буханка","вид":"устойчивые","rle":"b2o$o2bo$bobo$2bo!"},{"имя":"Лодка","вид":"устойчивые","rle":"2o$obo$bo!"},{"имя":"R-пентамино","вид":"долгожители","rle":"b2o$2ob$bo!"},{"имя":"Желудь","вид":"долгожители","rle":"bo5b$3bo3b$2o2b3o!"},{"имя":"Диехард","вид":"долгожители","rle":"6bob$2o6b$bo3b3o!"},{"имя":"Репликатор (для B36/S23)","вид":"другие правила","rle":"2b3o$bo2bo$o3bo$o2bob$3o!"}];
const ЛИСТ = 'Жизнь', R0 = 1, C0 = 1, ПРЕДЕЛ_Ш = 200, ПРЕДЕЛ_В = 150;
const ПРАВИЛА = {
  'Жизнь (B3/S23)': 'B3/S23', 'Высокая жизнь (B36/S23)': 'B36/S23', 'День и ночь (B3678/S34678)': 'B3678/S34678',
  'Семена (B2/S)': 'B2/S', 'Лабиринт (B3/S12345)': 'B3/S12345', 'Коралл (B3/S45678)': 'B3/S45678',
  'Репликатор (B1357/S1357)': 'B1357/S1357', 'Жизнь без смерти (B3/S012345678)': 'B3/S012345678',
  'Мозг Брайана (три состояния)': 'мозг', 'Одномерный автомат (правило 0–255)': 'одномерный', 'Своё правило': 'своё',
};
const ВОЗРАСТ = [[1, '#ffb547'], [3, '#f26d5b'], [10, '#c94f8c'], [50, '#6a5acd'], [Infinity, '#2f5fb3']];
const РАЗМЕРЫ = {'Мелкие (10 точек)': 10, 'Средние (14 точек)': 14, 'Крупные (20 точек)': 20};
let ж = null, таймер = null, частота = 0, тишинаДо = 0;

/* ---------- состояние ---------- */
function как(){
  const п = параметры({});
  const выбор = ПРАВИЛА[п.правило] || 'B3/S23';
  if(выбор === 'мозг') return {вид: 'мозг', тор: !!п.тор, текст: 'мозг Брайана'};
  if(выбор === 'одномерный') return {вид: 'одномерный', номер: Math.max(0, Math.min(255, Math.round(+п.номер || 30))), тор: !!п.тор, текст: 'правило ' + (Math.round(+п.номер) || 30)};
  const т = выбор === 'своё' ? (п.своё || 'B3/S23') : выбор;
  return {вид: 'bs', правило: ЖИЗНЬ.правило(т), тор: !!п.тор, текст: 'B' + ЖИЗНЬ.правило(т).b + '/S' + ЖИЗНЬ.правило(т).s};
}
function цветКлетки(v, возраст, п){
  if(v === 2) return '#ff8f3a';
  if(п.возраст) return ВОЗРАСТ.find(([д]) => возраст <= д)[1];
  return п.цвет || '#2f5fb3';
}
function нарисовать(){
  if(!ж) return;
  const п = параметры({}), {w, h, поле} = ж, out = [];
  for(let r = 0; r < h; r++){
    let c = 0;
    while(c < w){
      const i = r * w + c, v = поле.к[i];
      if(!v){ c++; continue; }
      const цв = цветКлетки(v, поле.в[i], п);
      let c2 = c;
      while(c2 + 1 < w && поле.к[i + c2 + 1 - c] && цветКлетки(поле.к[i + c2 + 1 - c], поле.в[i + c2 + 1 - c], п) === цв) c2++;
      out.push({область: АДРЕС(R0 + r, C0 + c) + (c2 > c ? ':' + АДРЕС(R0 + r, C0 + c2) : ''), заливка: цв});
      c = c2 + 1;
    }
  }
  лист(ЛИСТ).декорации('жизнь', out);
  счёт();
}
function счёт(){
  if(!ж) return;
  const n = ЖИЗНЬ.живых(ж.поле);
  const части = [{текст: 'Поколение ' + ж.поколение, жирный: true}, {текст: '  ·  живых ' + n.toLocaleString('ru-RU')}];
  if(ж.повтор) части.push({текст: '  ·  ' + ж.повтор, цвет: '#b26a00'});
  if(таймер) части.push({текст: '  ·  идёт', цвет: '#2a8a4a'});
  панель.поле('счёт', части);
}
function рамка(){
  лист(ЛИСТ).декорации('рамка', [{область: ОБЛАСТЬ(R0, C0, R0 + ж.h - 1, C0 + ж.w - 1), рамка: '#8a96ad', толщина: 2}]);
}
function запомнитьПоле(){
  if(!ж) return;
  try { лист(ЛИСТ).запомнить('жизнь', {w: ж.w, h: ж.h, точек: ж.точек, rle: ЖИЗНЬ.вRLE(ж.поле), поколение: ж.поколение}); } catch(e){}
}
function сбросПовторов(){ ж.отпечатки = new Map(); ж.повтор = ''; }
/* «Сброс» возвращает узор, с которого начался последний ход после правок человека */
function начальноеСохранить(){ if(!ж.начало) ж.начало = {к: ж.поле.к.slice(), в: ж.поле.в.slice(), строка: ж.строка}; }

/* ---------- поле на черновом листе ---------- */
async function завестиПоле(w, h, точек){
  w = Math.max(8, Math.min(ПРЕДЕЛ_Ш, Math.round(w))); h = Math.max(8, Math.min(ПРЕДЕЛ_В, Math.round(h)));
  await книга.черновик(ЛИСТ);
  const api = Api.GetSheet(ЛИСТ);
  api.GetRange(ОБЛАСТЬ(0, 0, 0, C0 + w)).SetColumnWidth(точек / 7);
