function положитьФигуру(ф, r0, c0){
  let вне = 0;
  for(const [r, c] of ф.клетки){
    const rr = r0 + r, cc = c0 + c;
    if(rr < 0 || rr >= ж.h || cc < 0 || cc >= ж.w){ вне++; continue; }
    ж.поле.к[rr * ж.w + cc] = 1; ж.поле.в[rr * ж.w + cc] = 1;
  }
  return вне;
}
/* где поставить фигуру: у курсора, если он на поле, иначе посередине */
function местоФигуры(ф){
  const в = книга.выделение || {};
  if(в.лист === ЛИСТ){
    const r = в.r1 - 1 - R0, c = в.c1 - 1 - C0;
    if(r >= 0 && r < ж.h && c >= 0 && c < ж.w) return [Math.max(0, Math.min(r, ж.h - ф.h)), Math.max(0, Math.min(c, ж.w - ф.w))];
  }
  return [Math.floor((ж.h - ф.h) / 2), Math.floor((ж.w - ф.w) / 2)];
}
async function нужноПоле(){
