/* ---------- ход ---------- */
function шаг(){
  const к = как();
  начальноеСохранить();
  if(к.вид === 'одномерный' && ж.строка == null){
    /* одномерному нужна стартовая строка: первая непустая, а если пусто — одна клетка посередине верхней */
    let r = 0; while(r < ж.h && !ж.поле.к.subarray(r * ж.w, (r + 1) * ж.w).some(Boolean)) r++;
    if(r >= ж.h){ r = 0; ж.поле.к[Math.floor(ж.w / 2)] = 1; ж.поле.в[Math.floor(ж.w / 2)] = 1; }
    ж.строка = r;
    ж.начало = null; начальноеСохранить();
  }
  const р = ЖИЗНЬ.шаг(ж.поле, Object.assign({строка: ж.строка}, к));
  ж.поле = р.п; if(р.строка != null) ж.строка = р.строка;
  ж.поколение++;
  const n = ЖИЗНЬ.живых(ж.поле);
  ж.история.push(n); if(ж.история.length > 100000) ж.история.shift();
  if(к.вид !== 'одномерный'){
    const о = ЖИЗНЬ.отпечаток(ж.поле), был = ж.отпечатки.get(о);
    if(!n) ж.повтор = 'поле опустело';
    else if(был != null){ const п = ж.поколение - был; ж.повтор = п === 1 ? 'поле замерло' : 'повторяется с периодом ' + п; }
    ж.отпечатки.set(о, ж.поколение);
    if(ж.отпечатки.size > 400){ const первый = ж.отпечатки.keys().next().value; ж.отпечатки.delete(первый); }
  }
  return n;
}
function остановить(){ if(таймер){ clearInterval(таймер); таймер = null; } }
